1	// WHEN A BLOCKED ITEM MAY RUN (tasks-dispatch DESIGN §9, decision §15.19,
2	// reversed by decision §15.31 / #1373). One caller asks this question: the
3	// scheduler run, hourly, over every open item. A close does not — releasing a
4	// dependent is deciding whether the world has moved on, which is what the
5	// scheduler run exists to re-derive, and a task execution converging its own
6	// item has no business relabelling a sibling work item to answer it.
7	//
8	// The backstop framing survives the reversal unchanged: nothing but the
9	// scheduler run's hourly pass ever releases a blocked item, so a chain link
10	// waits at most one scheduler run for its dependency to be noticed.
11	
12	import { STATUS_BLOCKED, isStatus, parseWorkItemBody } from './work-item.mjs';
13	
14	// Is this item's wait over? `stateOf(n)` answers the state of a `Blocked-by`
15	// target that may not be a work item at all — an unknown number is never treated
16	// as closed, so an unreadable blocker DELAYS rather than releases (the
17	// convergence-not-prevention posture). An item in triage is nobody's to release.
18	export function isReleasable(item, { stateOf = () => null, nowMs = Date.now() } = {}) {
19	  if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED)) return false;
20	  const { notBefore, blockedBy } = parseWorkItemBody(item.body);
21	  const blockersDone = blockedBy.every((n) => stateOf(n) === 'closed');
22	  const timeReached = notBefore === null || nowMs >= new Date(notBefore).getTime();
23	  return blockersDone && timeReached;
24	}
25

