1	// The production-retrospective skill (#1501) rides the same request lane as
2	// verify-in-production — the queue is the delayed-execution mechanism, so the
3	// skill's whole contract is prose. What is tested is that the template it
4	// prescribes is one the queue's own parsers read back.
5	import { test } from 'node:test';
6	import assert from 'node:assert/strict';
7	import { readFileSync } from 'node:fs';
8	import { join, dirname } from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	import { parseRequestFields } from '../../claudinite-tasks/queue/work-item.mjs';
11	import { parseRetryEvery, RETRY_FIELD } from '../../claudinite-tasks/tasks/verify-production/probes.mjs';
12	
13	const skill = readFileSync(
14	  join(dirname(fileURLToPath(import.meta.url)), '../skills/production-retrospective/SKILL.md'), 'utf8');
15	
16	// The template is the fenced block that opens on the wait fields. Its
17	// `<placeholder>` values are filled with one plausible value per field, and the
18	// "(chain case)" / "(merge case)" annotations beside them are template commentary,
19	// not body text.
20	const template = [...skill.matchAll(/```\n([\s\S]*?)```/g)].map((m) => m[1]).find((b) => b.startsWith('Blocked-by:'));
21	const SAMPLES = { 'Blocked-by': '#1700', 'Not-before': '2026-09-17T00:00:00Z' };
22	const filled = template.split('\n').map((line) => {
23	  const field = /^([A-Za-z-]+):/.exec(line)?.[1];
24	  return field && line.includes('<') && SAMPLES[field] ? `${field}: ${SAMPLES[field]}` : line.replace(/\s+\([a-z ]+ case\)\s*$/, '');
25	}).join('\n');
26	
27	test('the queue reads the retrospective template back: both waits, an opus session, a re-arm cadence, nothing to merge', () => {
28	  const fields = parseRequestFields(filled, { gated: true });
29	  assert.deepEqual(fields.blockedBy, [1700], 'the chain case waits on the final link');
30	  assert.equal(fields.notBefore, SAMPLES['Not-before'], 'the merge case sleeps to the horizon');
31	  assert.equal(fields.model, 'opus', 'an open review is judgment work, not a field read');
32	  assert.equal(fields.merge, null, 'a retrospective has nothing to merge');
33	  const retry = new RegExp(`^${RETRY_FIELD}:[ \\t]*(.+)$`, 'm').exec(filled)?.[1];
34	  assert.ok(parseRetryEvery(retry) > 0, `${RETRY_FIELD} must read as a cadence, or a thin record cannot re-arm`);
35	});
36

