// silently, in different ways.
//
// THIS FILE RUNS IN ONE PLACE: INSIDE A WORK-ITEM SESSION. `queue/instructions.md`
// step 6 is its only caller — no workflow invokes it, no module imports it. The
// Actions side converges through `executor.mjs`, which owns that path entirely.
//
// SO EVERY LINE HERE ASSUMES MCP, AND NOTHING HERE MAY REACH THE NETWORK. A session
// holds its GitHub access through its own tools; a subprocess it spawns has no route
// to them and none to the REST API. This file therefore PLANS a transition and
// PRINTS it addressed to those tools — it never performs one. Printing the calls is
// the successful outcome, on stdout, exit 0. That is not a fallback: it is the only
// path, and it must never read as a failure. A REST executor lived here once and did
// (#1491) — a session met its `console.error` before it met the path written for it,
// reported that it could not converge, and left the item to the janitor's 3h leash,
// which parks a finished run as a human decision. Five sampled items across five
// repos were exactly that.
//
// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
// JUDGMENT — which outcome, and the prose of what happened — and the CODE decides
// every step of the transition. A session that stops early now leaves an item that
// is visibly unconverged, rather than one that looks finished and is not.
//
// Usage — the item is handed in, because this process cannot read it:
//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
//                          --summary <text> [--pr <n>]
//                          --repo <owner/name> --item-file <path to the issue as JSON>

import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { renderTaskExec } from '../run-record.mjs';
import {
  AGENT, TASK_DONE, STATUS_RUNNING_AGENT, isStatus, machineBlockOf,
  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
  QUEUED_LABEL, IN_REVIEW_LABEL, ORIGIN_LABELS, hasLabel,
  parseWorkItemTitle, parseWorkItemBody, spellingsOf, labelNames,
  editItemBody, withEndsWhen,
} from './work-item.mjs';

// What a session may claim, and what each one means for the item. `record` is the
// execution-record status, and `null` means no record: an approval park is a run
// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
// a fifth status would be stored data every decoder in the fleet must learn.
export const OUTCOMES = Object.freeze({
  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
});

export function parseArgs(argv) {
  const args = {};
  for (let n = 0; n < argv.length; n += 1) {
    const m = /^--([a-z-]+)$/.exec(argv[n]);
    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
  }
  const issue = Number(args.issue);
  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
  if (!OUTCOMES[args.outcome]) {
    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
  }
  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
  if (args.outcome === 'approval' && !args.pr) {
    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
  }
  return {
    issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null,
    repo: args.repo || null, itemFile: args['item-file'] || null,
  };
}

// Why an item may NOT be converged by this call. Refusing loudly beats writing a
// terminal state onto the wrong issue: this runs from a session, whose whole
// notion of which item it holds came from an untrusted fire payload.
export function refusal(item, issue) {
  if (!item) return `#${issue} could not be read`;
  // A marked issue IS its own item (DESIGN §16.1), so the title test cannot be the
  // membership test any more: what says this is one is the machine block adoption
  // wrote — never the body's first line, which on a marked issue is a person's prose.
  //
  // THREE SIGNALS, ANY ONE SUFFICIENT. A membership test gated on the single artifact
  // it exists to validate refuses exactly the items that artifact is missing from: an
  // issue adopted before the block delimiters existed carries its fields bare, and was
  // refused here into a by-hand convergence that dropped half the transition
  // (missingbulb/Shepherd#360). The origin label is the independent one — carried for
  // life, and platform-write-gated like the block was.
  const marked = ORIGIN_LABELS.some((name) => hasLabel(item, name));
  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null && !marked) {
    return `#${issue} is not a Claudinite work item`;
  }
  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
  }
  return null;
}

// The record line for this item, or null where the vocabulary has no true answer.
export const recordLine = (item, status) => {
  const parsed = parseWorkItemTitle(item.title);
  return status && parsed
    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
    : null;
};

// The comment one converge writes: the session's account, then the record, so a
// reader and a parser both find what they came for in one place.
export function convergeComment(item, { summary, pr, record }) {
  const rec = recordLine(item, record);
  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
  return `${summary.trim()}${waiting}${line}`;
}

// THE TRANSITION AS DATA (#1374). The side effects were a straight line of
// `await api.…` calls, which silently made REST the only way to perform them —
// and the sessions `invoke.mjs` hands work to have no REST route to their own
// repository, so the last step of every agentic run was the one step that
// environment could not take.
//
// So the sequence is planned as OPS and executed by whoever can. The planner is
// the single source of what a convergence IS; the executors differ only in
// transport. The session still supplies nothing but the judgment.
//
// Removes are granular and unconditional — every spelling of the status being
// left, not only the ones this snapshot shows (apply-status.mjs's rule: a member's
// items outlive its converges, so an item may wear an older engine's spelling).
export function convergeOps(item, plan) {
  const spec = OUTCOMES[plan.outcome];
  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record }) }];

  // The record goes to BOTH sinks, and neither is redundant: the comment above is
  // the durable one (Actions logs expire, the item does not), while this printed
  // copy lands in the session transcript, which is what the usage fold reads for
  // the task-status census.
  const rec = recordLine(item, spec.record);
  if (rec) ops.push({ kind: 'record', line: rec });

  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
  }
  // ONE label, on both paths: the outcome IS the status. A park in particular is
  // never a pair, so nothing can be half-applied (#1385).
  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });

  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
  // merge or close the pull request; this says the same thing where the janitor can
  // read it, so the item ends when that happens instead of waiting for someone to
  // notice it already did. Every park that names one gets it, not only `approval`.
  if (!spec.closes && plan.pr) {
    ops.push({ kind: 'setBody', issue: item.number, body: editItemBody(item.body, (m) => withEndsWhen(m, plan.pr)) });
  }

  // SUPERSEDING (DESIGN §6.4b). The executor decided at resolution which of this
  // task's earlier pull requests a `supersede_existing_pr` run replaces and stamped
  // them on the item; they close only once THIS run's own pull request exists — a
  // run that delivered nothing, or broke, leaves them where they were, so a review
  // member's pending pull request is never taken away for nothing.
  const { supersedes } = parseWorkItemBody(item.body ?? '');
  if (plan.pr && (plan.outcome === 'done' || plan.outcome === 'approval')) {
    for (const number of supersedes) {
      ops.push({ kind: 'closePull', number, successor: plan.pr, body: `Superseded by #${plan.pr}, a later run of the same task. Closing this one.` });
    }
  }

  if (spec.closes) {
    // A DONE TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed (#1489,
    // reversing §16.1/§16.5's "never a marked issue"). `done` is the one outcome
    // that means nothing is left for anyone to act on, so an issue left open under
    // it asks its author to come and agree with what the run already settled. Every
    // other outcome parks, and a park leaves the issue open to be waited on.
    ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
    return ops;
  }

  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
  // (§16.5). Only the approval park: a failure deliberately writes nothing and
  // leaves `claude-queued` standing, because re-arming work that writes code is a
  // person's decision and that standing label is what stops the next scheduler run
  // queueing a second run of the same request. Only a LEGACY shadow item writes
  // back to a different issue.
  const { request } = parseWorkItemBody(item.body ?? '');
  if (request && request !== item.number && plan.outcome === 'approval') {
    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
    ops.push({ kind: 'removeLabel', issue: request, name: QUEUED_LABEL });
    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
  }
  return ops;
}

// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
// does have. Two differences forced by that surface, both handled here rather than
// left to the session to work out:
//
//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
//    granular removes and adds are folded into the FINAL set here, computed from the
//    labels this item was read with. Everything not a status label is carried through.
//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
//    usage fold reads the census out of the session transcript.
export function sessionScript(item, plan, repo) {
  const [owner, name] = String(repo).split('/');
  const lines = [];
  let n = 0;
  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };

  // The item's own label set can be computed exactly, because the item was read
  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
  // read-modify-write naming only the change, and never as a computed set, which
  // would silently drop every label this process never saw.
  const own = new Set(labelNames(item));
  const foreign = [];
  // The body write folds into the item's own `issue_write`, which is one call
  // either way. A park never closes, so the step it folds into is the trailing
  // label write below.
  let newBody = null;

  for (const op of convergeOps(item, plan)) {
    if (op.kind === 'comment') {
      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
    } else if (op.kind === 'record') {
      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
      if (op.issue === item.number) {
        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
      } else {
        foreign.push(op);
      }
    } else if (op.kind === 'setBody' && op.issue === item.number) {
      newBody = op.body;
    } else if (op.kind === 'close') {
      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
      own.clear();
    } else if (op.kind === 'closePull') {
      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.number}\` (a pull request), body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
      step(`\`update_pull_request\` — owner \`${owner}\`, repo \`${name}\`, pullNumber \`${op.number}\`, state \`closed\``);
    }
  }
  // A park never closed, so its label write is still owed.
  if (own.size) {
    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
      + ` labels \`${JSON.stringify([...own])}\``
      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
  }
  for (const op of foreign) {
    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
      + ` Read that issue's current labels first and write them back with only this one change —`
      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
  }
  return lines.join('\n');
}

async function main() {
  const plan = parseArgs(process.argv.slice(2));
  if (plan.error) {
    console.error(`converge-item: ${plan.error}`);
    process.exit(2);
  }

  // The repo this item lives in. `--repo` is what instructions.md passes; the two
  // environment names answer for a session whose harness sets one of them.
  const repo = plan.repo ?? process.env.CLAUDINITE_ITEM_REPO ?? process.env.GITHUB_REPOSITORY ?? null;
  if (!repo) {
    console.error('converge-item: --repo <owner/name> names the repository this item lives in');
    process.exit(2);
  }

  // THE ITEM IS HANDED IN. This process cannot read it — that is the whole premise
  // of the file — so the session reads it with its own tools and passes it through.
  // A file rather than an argument: an item's body is prose of arbitrary length, and
  // a shell-quoted one is a quoting bug waiting for the first apostrophe.
  // `CLAUDINITE_ITEM_JSON` stays readable for a member whose instructions.md is a
  // cycle behind, since a mount updates on its own schedule.
  const raw = plan.itemFile
    ? await readFile(plan.itemFile, 'utf8')
    : (process.env.CLAUDINITE_ITEM_JSON ?? '');
  let item = null;
  try { item = JSON.parse(raw || 'null'); } catch { item = null; }
  if (!item) {
    console.error('converge-item: --item-file must hold the issue as your GitHub tools returned it'
      + ' (number, title, body, state, labels).\n'
      + `Read it first: \`issue_read\` method \`get\` on ${repo} #${plan.issue}, save the JSON, pass the path.`);
    process.exit(2);
  }

  const no = refusal(item, plan.issue);
  if (no) { console.error(`converge-item: ${no}`); process.exit(1); }

  // The successful outcome. Everything below is the transition, decided here and
  // performed by the session — so it goes to stdout and the process exits clean.
  console.log('converge-item: the transition below is yours to execute.\n'
    + 'Make these calls with your GitHub tools, in this order, changing nothing. Then stop.\n');
  console.log(sessionScript(item, plan, repo));
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(e); process.exit(1); });
}

// The work item — the queue's one durable object (tasks-dispatch DESIGN §3, §4).
// An issue titled `[claudinite-work] <pack>/<task> [qualifier]`, whose labels are
// its state, whose body's first line is the task path, and whose optional body
// fields (`Not-before`, `Blocked-by`, and a request's `Request` / `Model`) are the
// only facts it carries beyond that.
//
// PURE, and deliberately the whole schema: everything else — anchors, guards,
// yields, leashes, verdicts — is computed fresh at every scheduler run and pick from the
// engine and the declarations at HEAD (DESIGN §14). The label-and-field vocabulary
// here is therefore the compatibility surface across engine versions, which is why
// additive change is the strongly preferred shape and a rename needs a migration.
//
// Parse/serialize of those fields lives here and nowhere else (DESIGN §9).
//
// The one import, and a frozen constant at that: the pack-rename map, which this
// module needs to keep reading titles written before a rename (see parseWorkItemTitle).
import { canonicalPackId } from '../../../engine/pack_loader/renamed-packs.mjs';

// The title prefix. Disjoint from the slot mechanism's `[claudinite-task]` on
// purpose: the two mechanisms coexist per-repo behind `taskScheduler.dispatch`,
// and neither may read the other's issues (DESIGN §14, S29).
export const WORK_PREFIX = '[claudinite-work]';

// --- the canonical vocabulary (DESIGN §4, the migration of #1119) -------------
// Every label the machinery writes is one of three things — the item's single
// STATUS, its lifelong ORIGIN, or the URGENCY flag — and all of them live in the
// `task:` namespace. These are the spellings a reader compares against: decode
// first (`statusOf`, `originOf`), then compare, so an item filed by any engine
// version answers the same question the same way.
export const STATUS_PREFIX = 'task:status:';
export const PARK_PREFIX = `${STATUS_PREFIX}needs-human-`;

export const STATUS_BLOCKED = `${STATUS_PREFIX}blocked`;
export const STATUS_READY = `${STATUS_PREFIX}waiting-for-executor`;
export const STATUS_RUNNING_EXECUTOR = `${STATUS_PREFIX}running-executor`;
export const STATUS_RUNNING_AGENT = `${STATUS_PREFIX}running-agent`;
export const STATUS_NEEDS_HUMAN_ACTION = `${PARK_PREFIX}action`;
export const STATUS_NEEDS_HUMAN_DECISION = `${PARK_PREFIX}decision`;
export const STATUS_NEEDS_HUMAN_APPROVAL = `${PARK_PREFIX}approval`;
export const STATUS_NEEDS_HUMAN_FAILURE = `${PARK_PREFIX}failure`;
export const STATUS_DONE = `${STATUS_PREFIX}done`;
export const STATUS_REJECTED = `${STATUS_PREFIX}rejected`;

// The four statuses an OPEN item may wear before it parks or converges. An open
// item wearing no decodable status at all is off the state machine — a torn label
// swap's leavings, which the janitor repairs (DESIGN §6.2, §11).
export const LIVE_STATUSES = Object.freeze([
  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
]);
// The park kinds, in the order a decoder prefers them when an item somehow wears
// more than one: `failure` first, because it is the conservative lane — the one
// that holds the task's lane rather than letting a broken task keep filing work.
export const PARK_KINDS = Object.freeze(['failure', 'action', 'decision', 'approval']);
export const PARK_STATUSES = Object.freeze(PARK_KINDS.map((k) => `${PARK_PREFIX}${k}`));
export const STATUS_LABELS = Object.freeze([
  ...LIVE_STATUSES, ...PARK_STATUSES, STATUS_DONE, STATUS_REJECTED,
]);

// THE ORIGIN (DESIGN §3, decision §15.29) — who asked for this item, worn for the
// item's whole life beside whatever status it holds. Read here; the writers arrive
// with the write-side flip.
export const ORIGIN_PREFIX = 'task:origin:';
export const ORIGIN_PLANNED = `${ORIGIN_PREFIX}planned`;
// The two shapes a person's ask takes, which were one label until the trigger
// field made them nameable apart (#1725). `manual` is an occurrence of a DECLARED
// task somebody pulled the lever on — a wake, a hand-created item — so the queue
// already knows what work it is. `ad-hoc` is somebody's own issue, adopted as
// itself, which every time runs the same task (`implement-request`) over a
// different subject.
export const ORIGIN_MANUAL = `${ORIGIN_PREFIX}manual`;
export const ORIGIN_AD_HOC = `${ORIGIN_PREFIX}ad-hoc`;
export const ORIGIN_GITHUB = `${ORIGIN_PREFIX}github`;
export const ORIGIN_LABELS = Object.freeze([ORIGIN_PLANNED, ORIGIN_MANUAL, ORIGIN_AD_HOC, ORIGIN_GITHUB]);
// Every origin that is somebody asking. The scheduler files only ORIGIN_PLANNED,
// so this is its complement among the origins a person's action produces.
export const ASKED_FOR_ORIGINS = Object.freeze([ORIGIN_MANUAL, ORIGIN_AD_HOC]);

// --- the write spellings ------------------------------------------------------
// What this engine APPLIES — the canonical vocabulary above, since the write-side
// flip (#1119). The names survive the flip because fielded pack versions import
// them: a pack still on the old engine's spelling writes a legacy label, which
// every decoder here reads as the status it always meant.
export const BLOCKED = STATUS_BLOCKED;
export const READY = STATUS_READY;
export const URGENT = 'task:urgent';
export const EXECUTING = STATUS_RUNNING_EXECUTOR;
export const AGENT = STATUS_RUNNING_AGENT;
export const TASK_DONE = STATUS_DONE;
export const TASK_OBSOLETE = STATUS_REJECTED;

// --- the legacy spellings, written never and read forever ----------------------
// Every spelling any fielded engine has written. They are literals rather than
// aliases of the constants above precisely because those constants moved: a decode
// map built from them would have mapped today's spelling to itself and forgotten
// the vocabulary it exists to read (DESIGN §4).
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_BLOCKED = 'task:blocked';
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_READY = 'task:ready';
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_EXECUTING = 'task:executing';
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_AGENT = 'task:agent';

// @deprecated The bare park of the two-label era. A park is ONE label now
// (`task:status:needs-human-<kind>`); this is still read — on its own it decodes to
// `failure`, the conservative lane — and still ensured, because an open item filed
// by a fielded engine wears it.
export const NEEDS_HUMAN = 'needs-human';

// @deprecated Nothing writes this since the approval park: a run that left an
// unmerged PR no longer CLOSES as delivered, it parks at the approval lane and
// waits to be merged. Kept exported, kept in `QUEUE_LABELS`, and still read
// everywhere it was read — closed issues carrying it are stored data, and a decoder
// that stopped recognising it would turn every historical delivered run into an
// un-outcomed one.
export const OUTCOME_DELIVERED = 'outcome:delivered';

// @deprecated The pre-2026-08-19 terminal spellings. Kept exported so a fielded
// pack that imports them still loads, and READ wherever an outcome is decoded:
// labels are stored data on closed issues fleet-wide, so a decoder that stopped
// recognising these would turn every historical run into an un-outcomed one.
export const OUTCOME_DONE = 'outcome:done';
export const OUTCOME_OBSOLETE = 'outcome:obsolete';

// @deprecated The pre-#1119 terminal spellings in the `task:` namespace, the
// generation between `outcome:*` and today's statuses. Read forever, same reason.
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_TASK_DONE = 'task:done';
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_TASK_OBSOLETE = 'task:obsolete';

// @deprecated The origin marker (DESIGN §15.26). Nothing writes it and nothing
// branches on it: whether an item is a task's standing occurrence or an ad-hoc run
// is STRUCTURAL — see `isStandingItem` — so a marker that could disagree with the
// structure was a second authority over the same fact. Kept exported and inert
// because open items filed by an older engine still carry it, and a reader that
// choked on an unknown label would fail on exactly those.
export const ORIGIN_SCHEDULE = 'origin:schedule';

// THE PARK KINDS. A park is ONE label since the flip — `task:status:needs-human-<kind>`
// — and the kind is what the human is being asked for, which is the whole
// difference between a queue a person can skim and one they have to read.
//
// The four are disjoint by REMEDY, not by cause:
//   action   — something outside the code must change: a secret set, a scope
//              granted, a routine's prompt or endpoint fixed, an item re-created
//              with the parameter it was missing. Mechanical; no judgement.
//   decision — the run stopped mid-flight and what happens next is a choice:
//              re-queue or abandon, does the half-done work stand, was the
//              ceiling violation acceptable.
//   approval — the run SUCCEEDED and deliberately left an unmerged PR. The only
//              park that is not a fault; the human merges it or closes it.
//   failure  — the run broke: a bug, a contract-forbidden shape, a malformed or
//              forged item. Someone diagnoses and fixes code.
// `failure` is the default a park falls back to, so an unclassified park reads as
// "diagnose me" rather than quietly joining the mechanical lane.
//
// The names are the ones fielded packs import; their VALUES are today's park
// statuses. The two-label era's sub-labels (`task:needs-human-<kind>`) are read by
// `parkOf` below and written by nobody.
export const NEEDS_HUMAN_ACTION = STATUS_NEEDS_HUMAN_ACTION;
export const NEEDS_HUMAN_DECISION = STATUS_NEEDS_HUMAN_DECISION;
export const NEEDS_HUMAN_APPROVAL = STATUS_NEEDS_HUMAN_APPROVAL;
export const NEEDS_HUMAN_FAILURE = STATUS_NEEDS_HUMAN_FAILURE;
export const TRIAGE_LABELS = PARK_STATUSES;

// WHICH PARK IS A BROKEN RUN. A park is not live, so no park holds its task's lane by
// itself: the scheduler asks the task again on its own conditions, and only a task
// declaring `last-run-not-failed` stops past its own failure. What this predicate
// tells apart is the park a person DIAGNOSES from the three that are a person's
// inbox — a PR waiting to be approved, a choice waiting to be made, a secret waiting
// to be set — which is the split every renderer alarms on and the run-history term
// reads (`parkKindOf`).
//
// A park wearing NO sub-label counts as broken, which is what makes this safe on the
// way in: every item parked by an engine older than the sub-labels, and every kind
// word a future engine invents that this one does not know, reads as "diagnose me"
// rather than quietly joining the mechanical lane.
export const isBlockingPark = (item) => statusOf(item) === STATUS_NEEDS_HUMAN_FAILURE;

// --- the decode (DESIGN §4, "legacy spellings — written never, read forever") --
// Labels are STORED DATA: open items filed by a fielded engine wear its spellings,
// closed items keep theirs forever, and members converge on their own schedules. So
// every reader here goes through one pass that maps every spelling ever written
// straight to today's — never through a literal comparison against one of them.
// @legacy-tolerance advisory:none retire:#1642
const LEGACY_STATUS = new Map([
  [LEGACY_BLOCKED, STATUS_BLOCKED],
  [LEGACY_READY, STATUS_READY],
  [LEGACY_EXECUTING, STATUS_RUNNING_EXECUTOR],
  [LEGACY_AGENT, STATUS_RUNNING_AGENT],
  [LEGACY_TASK_DONE, STATUS_DONE], [OUTCOME_DONE, STATUS_DONE],
  [LEGACY_TASK_OBSOLETE, STATUS_REJECTED], [OUTCOME_OBSOLETE, STATUS_REJECTED],
]);

// @legacy-tolerance advisory:none retire:#1642
const LEGACY_PARK_RE = /^task:needs-human-(.+)$/;

// The park an issue's labels name, canonical, or null. Both shapes decode here:
// today's single `task:status:needs-human-<kind>` and the legacy pair
// (`needs-human` plus a sub-label). A kind nobody here knows — a bare legacy park,
// or a word a newer engine invented — reads as `failure`, the conservative lane.
function parkOf(names) {
  const kinds = [
    ...names.filter((n) => n.startsWith(PARK_PREFIX)).map((n) => n.slice(PARK_PREFIX.length)),
    ...names.map((n) => LEGACY_PARK_RE.exec(n)?.[1]).filter(Boolean),
  ];
  if (!kinds.length && !names.includes(NEEDS_HUMAN)) return null;
  return `${PARK_PREFIX}${PARK_KINDS.find((k) => kinds.includes(k)) ?? 'failure'}`;
}

// Every distinct status an issue's labels decode to. One entry per status, so an
// item mid-flip — wearing a legacy spelling beside its canonical one — reads as the
// ONE status it is, and only genuinely conflicting labels read as more than one
// (the dashboard's `torn`).
export function statusesOn(issue) {
  const names = labelNames(issue);
  const out = new Set();
  const park = parkOf(names);
  if (park) out.add(park);
  for (const n of names) {
    if (STATUS_LABELS.includes(n) && !n.startsWith(PARK_PREFIX)) out.add(n);
    else if (LEGACY_STATUS.has(n)) out.add(LEGACY_STATUS.get(n));
  }
  return [...out];
}

// THE status an issue wears, canonical, or null for one wearing none. A park wins
// over anything else present: a torn transition that left a state label beside a
// park must read as parked, or the queue would pick up an item a human owns.
export function statusOf(issue) {
  const worn = statusesOn(issue);
  return worn.find((s) => s.startsWith(PARK_PREFIX))
    ?? STATUS_LABELS.find((s) => worn.includes(s))
    ?? null;
}

export const isStatus = (issue, status) => statusOf(issue) === status;
export const isParked = (issue) => (statusOf(issue) ?? '').startsWith(PARK_PREFIX);
export const parkKindOf = (issue) =>
  (isParked(issue) ? statusOf(issue).slice(PARK_PREFIX.length) : null);

// The origin an issue wears, or null. Unlike the status there is no legacy
// spelling to fold in: `origin:schedule` is inert stored data (see ORIGIN_SCHEDULE),
// and reading it as an origin would put a marker nothing writes back into play.
export const originOf = (issue) =>
  labelNames(issue).find((n) => ORIGIN_LABELS.includes(n)) ?? null;

// Every spelling that MEANS `status` — what a transition out of it has to clear,
// since the item may wear any engine's. Leaving a park clears every park spelling
// whatever its kind: a re-queue takes the item out of the human's hands entirely.
export function spellingsOf(status) {
  if (String(status ?? '').startsWith(PARK_PREFIX)) {
    return [...PARK_STATUSES, ...PARK_KINDS.map((k) => `task:needs-human-${k}`), NEEDS_HUMAN];
  }
  const legacy = [...LEGACY_STATUS].filter(([, canonical]) => canonical === status).map(([l]) => l);
  return [status, ...legacy];
}

// THE RE-QUEUE LEVER, in words — one home, because it is written into every message
// that parks an item and a stale copy of it is an instruction that no longer works.
// Clearing the status IS the re-ask (DESIGN §16.3): a park is one label now, so
// there is nothing else to take off.
export const requeueHint = `clear its status label and add \`${STATUS_READY}\``;

// A kind word (from a worker's own triage marker, or a call site) to the park it
// names. Anything unrecognised is a `failure`: a worker that misspells its class has
// a bug, which is exactly what that lane means.
export const triageLabelFor = (kind) =>
  (PARK_KINDS.includes(kind) ? `${PARK_PREFIX}${kind}` : STATUS_NEEDS_HUMAN_FAILURE);


// The stored-data rename rule, decode side: every spelling ever written maps
// STRAIGHT to the canonical word, in one pass — including `outcome:delivered`,
// which nothing writes any more but closed issues carry forever.
const OUTCOME_WORDS = new Map([[STATUS_DONE, 'done'], [STATUS_REJECTED, 'obsolete']]);

// The one outcome an issue's labels carry, as the canonical word ('done',
// 'delivered', 'obsolete') or null. Everything that tallies or renders outcomes
// decodes through here, so a spelling change is one map entry and not a sweep.
export function outcomeOf(issue) {
  // `statusesOn` rather than `statusOf`: a closed item's terminal write is its
  // outcome even when a park label stands beside it, and park precedence is a
  // question about LIVE items — what the queue may pick up — not about history.
  const worn = statusesOn(issue);
  for (const [status, word] of OUTCOME_WORDS) if (worn.includes(status)) return word;
  return hasLabel(issue, OUTCOME_DELIVERED) ? 'delivered' : null;
}

